import pandas as pd

candidate_names = [
    "schema_dict", "schema_dictionary", "schema_df", "schema", 
    "dictionary_df", "metadata_df"
]

schema_df = None
for name in candidate_names:
    obj = globals().get(name)
    if isinstance(obj, pd.DataFrame):
        schema_df = obj
        print(f"Using schema dictionary dataframe: {name}")
        break

if schema_df is None:
    print("No schema dictionary dataframe found under common names.")
else:
    # Search rows containing the requested keywords in any string column
    keywords = ["timestamp", "canonical", "event-time", "legacy", "source-of-truth"]
    mask = pd.Series(False, index=schema_df.index)

    for col in schema_df.columns:
        if pd.api.types.is_string_dtype(schema_df[col]) or schema_df[col].dtype == "object":
            col_values = schema_df[col].astype(str).str.lower()
            for kw in keywords:
                mask |= col_values.str.contains(kw.lower(), na=False)

    matches = schema_df.loc[mask].copy()

    print("\nExact matching rows:")
    if matches.empty:
        print("No matching rows found.")
    else:
        print(matches.to_string(index=False))

        # Print columns that help identify the canonical timestamp
        print("\nRelevant metadata columns available:")
        for col in matches.columns:
            print(f"- {col}")
